const user = {
    profile: {
        getName: () => "Alice",
    }
};
console.log(user?.profile?.getName?.()); // "Alice"
console.log(user?.settings?.theme);       // undefined (에러 없음)

// 3. 논리 할당 연산자 (Logical Assignment)
let config = { timeout: 0, retry: null, debug: true };
config.timeout ??= 5000; // 0 유지 (nullish가 아니므로 평가 안 됨)
config.retry ??= 3;      // 3 할당 (null이므로 기본값 대입)
config.debug &&= false;  // false 할당 (기존 값이 truthy이므로 우변 실행)
