// 1. 정보 은닉(Private State)과 팩토리 함수
function createBankAccount(initialBalance) {
    let balance = initialBalance; // 외부에서 직접 접근 불가능한 private 변수

    return {
        deposit(amount) {
            if (amount <= 0) throw new Error("입금액은 0보다 커야 합니다.");
            balance += amount;
            return balance;
        },
        withdraw(amount) {
            if (amount > balance) throw new Error("잔액이 부족합니다.");
            balance -= amount;
            return balance;
        },
        getBalance() {
            return balance;
        }
    };
}

const account = createBankAccount(10000);
account.deposit(5000);
console.log("현재 잔액:", account.getBalance()); // 15000
