class BankVault {
    // ES2022 Private Field (#): 런타임 하드 캡슐화 (외부 접근 완전 차단)
    #masterKey;
    #balance = 0;

    // 정적 속성 및 정적 초기화 블록 (ES2022)
    static defaultCurrency;
    static {
        // 복잡한 정적 초기화 로직 실행 가능
        const env = "KRW";
        this.defaultCurrency = env;
        console.log("[STATIC INIT] 기본 통화 설정 완료:", this.defaultCurrency);
    }

    constructor(owner, initialKey) {
        this.owner = owner;       // 공개 필드
        this.#masterKey = initialKey; // 비공개 필드 초기화
    }

    deposit(amount, key) {
        if (key !== this.#masterKey) throw new Error("인증 실패!");
        this.#balance += amount;
        return this.#balance;
    }
}

const vault = new BankVault("김철수", "secure-999");
vault.deposit(100000, "secure-999");
