const p1 = Promise.resolve("데이터 A");
const p2 = new Promise((_, reject) => setTimeout(() => reject(new Error("네트워크 에러")), 50));
const p3 = Promise.resolve("데이터 C");

// 1. Promise.allSettled: 성공/실패 여부에 관계없이 모든 프라미스의 결과 보고서를 배열로 반환
Promise.allSettled([p1, p2, p3]).then((results) => {
    results.forEach((res, i) => {
        if (res.status === "fulfilled") {
            console.log(`[#${i} 성공]:`, res.value);
        } else {
            console.log(`[#${i} 실패]:`, res.reason.message);
        }
    });
});

// 2. Promise.any: 전달된 프라미스 중 가장 먼저 성공(fulfilled)한 값을 반환
Promise.any([p2, p3]).then((firstSuccess) => {
    console.log("최초 성공 데이터:", firstSuccess); // "데이터 C"
});

// ES2024: Promise.withResolvers()를 활용한 비동기 작업 큐 및 취소 토큰 구현
class AsyncActionQueue {
    #resolvers = [];

    // 다음 작업이 도착할 때까지 대기하는 Promise 생성
    waitForNextAction() {
        const { promise, resolve, reject } = Promise.withResolvers();
        this.#resolvers.push({ resolve, reject });
        return promise;
    }

    // 외부 이벤트가 발생했을 때 대기 중인 프라미스를 외부에서 직접 해결(Resolve)
    dispatchAction(actionData) {
        const resolver = this.#resolvers.shift();
        if (resolver) {
            resolver.resolve(actionData);
        }
    }
}

const queue = new AsyncActionQueue();
queue.waitForNextAction().then(data => console.log("처리된 액션:", data));
queue.dispatchAction({ type: "USER_LOGIN", id: 42 });

