grammar.example:
// 1. 무한 시퀀스 생성과 지연 평가 (메모리 절약)
function* idGenerator(prefix = "id") {
    let id = 1;
    while (true) {
        // yield 시점에 실행 정지, next() 호출 시 재개
        yield `${prefix}-${id++}`;
    }
}

const gen = idGenerator("user");
console.log(gen.next().value); // "user-1"
console.log(gen.next().value); // "user-2"

// 2. 양방향 데이터 교환 (next에 인자 전달)
function* chat() {
    const question = yield "안녕하세요! 질문을 입력해주세요.";
    console.log(`[제너레이터 내부 수신]: ${question}`);
    yield `"${question}"에 대한 답변입니다.`;
}

const conversation = chat();
console.log(conversation.next().value); // 첫 yield 출력
console.log(conversation.next("오늘 날씨 어때요?").value); // 질문 전달 및 두 번째 yield 수신

