// 1. WeakMap을 활용한 DOM 엘리먼트 메타데이터 저장 (메모리 누수 방지)
const elementMetadata = new WeakMap();

function attachMetadata(domElement, data) {
    elementMetadata.set(domElement, data);
}

let btn = document.createElement("button");
attachMetadata(btn, { clickCount: 0, trackingId: "btn-101" });

console.log(elementMetadata.get(btn).trackingId); // "btn-101"

// 버튼이 DOM에서 제거되고 변수 참조가 null이 되면,
// WeakMap에 저장된 데이터도 GC에 의해 백그라운드에서 자동 수거됨!
btn = null; // 메모리 누수 0

// 2. WeakSet을 활용한 안전한 인스턴스 식별 플래그
const safeInstances = new WeakSet();
class SecureWidget {
    constructor() {
        safeInstances.add(this);
    }
    doSecureWork() {
        if (!safeInstances.has(this)) throw new Error("비인가 객체");
        return "보안 작업 수행";
    }
}

