    { name: "당근", type: "채소", quantity: 25 },
    { name: "시금치", type: "채소", quantity: 5 },
];

// 1. Object.groupBy(): 문자열 키를 기준으로 프로토타입 없는 null 객체에 그룹화
const byType = Object.groupBy(inventory, (item) => item.type);
console.log("과일 목록:", byType["과일"]);
console.log("채소 목록:", byType["채소"]);

// 2. Map.groupBy(): 임의의 복합 객체나 불리언, 숫자를 키로 그룹화
const stockStatus = {
    inStock: { label: "재고 있음" },
    outOfStock: { label: "품절" },
};

const byStock = Map.groupBy(inventory, (item) => {
    return item.quantity > 0 ? stockStatus.inStock : stockStatus.outOfStock;
});
console.log("품절 품목 개수:", byStock.get(stockStatus.outOfStock).length); // 1

grammar.syntax:
const proxy = new Proxy(target, {
    get(target, prop, receiver) { ... },
    set(target, prop, value, receiver) { ... },
    has(target, prop) { ... },
    deleteProperty(target, prop) { ... }
});

grammar.example:
// 반응형 상태 추적 및 유효성 검증 프록시
const targetData = { name: "홍길동", age: 25 };

const validatorProxy = new Proxy(targetData, {
    get(target, prop, receiver) {
        console.log(`[READ] ${String(prop)} 프로퍼티 읽기 시도`);
        return Reflect.get(target, prop, receiver);
    },
    set(target, prop, value, receiver) {
        if (prop === "age") {
            if (typeof value !== "number" || value < 0) {
                throw new TypeError("나이는 0 이상의 숫자여야 합니다.");
            }
        }
        console.log(`[WRITE] ${String(prop)} =`, value);
        return Reflect.set(target, prop, value, receiver);
    }
});

validatorProxy.age = 30; // [WRITE] age = 30
console.log(validatorProxy.name); // [READ] name -> "홍길동"
// validatorProxy.age = -5; // TypeError 발생!

grammar.syntax:
Reflect.get(target, prop, receiver);
Reflect.set(target, prop, val, receiver);
Reflect.ownKeys(target);

grammar.example:
const parent = {
    _value: "부모",
    get value() {
        return this._value;
    }
};

const child = {
    _value: "자식"
};
Object.setPrototypeOf(child, parent);

// Proxy에서 Reflect를 사용할 때 receiver를 전달해야 하는 결정적 이유
const proxy = new Proxy(child, {
    get(target, prop, receiver) {
        // receiver를 넘겨주어야 게터(getter) 내부의 this가 프록시 인스턴스(child)로 올바르게 바인딩됨!
        return Reflect.get(target, prop, receiver);
    }
});

console.log(proxy.value); // "자식" (Reflect 없이 target[prop] 사용 시 "부모"가 출력되는 버그 발생)

