grammar.example:
// 1. == 의 기괴한 암묵적 변환 함정들
console.log(0 == false);        // true (false -> 0)
console.log("" == 0);           // true ("" -> 0)
console.log(null == undefined); // true (스펙상 상호 동등 허용)
console.log([1] == 1);          // true ([1] -> "1" -> 1)

// 2. === 엄격 비교 (타입이 다르면 즉시 false)
console.log(0 === false);       // false

// 3. Object.is(): NaN과 NaN 비교 및 +0과 -0 구분
console.log(NaN === NaN);            // false (자바스크립트 유일)
console.log(Object.is(NaN, NaN));    // true
console.log(Object.is(+0, -0));      // false

// 4. Symbol.toPrimitive 커스텀 변환 정의
const money = {
    amount: 50000,
    [Symbol.toPrimitive](hint) {
        if (hint === "number") return this.amount;
        if (hint === "string") return `${this.amount}원`;
        return this.amount;
    }
};
console.log(+money + 10000);   // 60000 (number hint)
console.log(`${money} 보유`);  // "50000원 보유" (string hint)

class DatabaseError extends Error {
    constructor(message, options) {
        super(message, options);
        this.name = "DatabaseError";
    }
}

async function fetchUserData(userId) {
    try {
        // 저수준 네트워크 라이브러리 호출 가정
        throw new TypeError("TCP Connection Reset by Peer");
    } catch (lowLevelError) {
        // ES2022: 에러 원인(cause)을 체이닝하여 고수준 비즈니스 에러로 래핑 재발생
        throw new DatabaseError(`사용자 #${userId} 데이터베이스 조회 실패`, {
            cause: lowLevelError,
        });
    }
}

(async () => {
    try {
        await fetchUserData(101);
    } catch (err) {
        console.error(`[고수준 에러]: ${err.name} - ${err.message}`);
        console.error(`[원천 원인 에러]: ${err.cause.name} - ${err.cause.message}`);
        // err.stack에 원천 저수준 스택 트레이스까지 완벽 보존됨!
    }
})();

// 1. 순환 참조를 가진 복합 객체 구성
const nodeA = { name: "Node A" };
const nodeB = { name: "Node B" };
nodeA.neighbor = nodeB;
nodeB.neighbor = nodeA; // 상호 순환 참조!

// 과거 방식: JSON.stringify는 크래시 발생
// JSON.stringify(nodeA); // TypeError: Converting circular structure to JSON

// 현대 표준: structuredClone은 순환 참조를 완벽하게 보존하며 깊은 복사 성공
const clonedGraph = structuredClone(nodeA);
console.log(clonedGraph.neighbor.name); // "Node B"
console.log(clonedGraph.neighbor.neighbor === clonedGraph); // true (순환 관계 유지!)

// 2. 다양한 내장 타입 복사
const complexData = {
    date: new Date(),
    pattern: /^[a-z]+$/gi,
    tags: new Set(["alpha", "beta"]),
    meta: new Map([["v", 1]]),
};
const clonedComplex = structuredClone(complexData);
console.log(clonedComplex.date instanceof Date); // true (Date 객체로 복원)
console.log(clonedComplex.tags instanceof Set);  // true (Set 객체로 복원)

// 1. toJSON() 커스텀 직렬화 메서드
const secretUser = {
    id: 101,
    passwordHash: "8f9b...",
    ssn: "900101-1234567",
    toJSON() {
        // 민감 정보 제거 후 직렬화 대상 객체 반환
        return { id: this.id };
    }
};
console.log(JSON.stringify(secretUser)); // '{"id":101}'

// 2. JSON.stringify의 replacer 배열 / 함수
const product = { id: 1, name: "키보드", price: 150000, internalNotes: "마진 20%" };
const publicJson = JSON.stringify(product, ["id", "name", "price"], 2); // 화이트리스트 키만 추출 및 들여쓰기 2칸
console.log(publicJson);

// 3. JSON.parse의 reviver 함수 (날짜 문자열을 Date 인스턴스로 즉시 복원)
const jsonPayload = '{"eventId": 10, "occurredAt": "2024-05-15T12:00:00.000Z"}';
const parsed = JSON.parse(jsonPayload, (key, value) => {
    if (key === "occurredAt") return new Date(value);
    return value;
});
console.log(parsed.occurredAt instanceof Date); // true!
